class Solution:
    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        dirs = [(-1, 0), (0, -1)]

        def dfs(i: int, j: int) -> None:
            grid[i][j] = 2

        # First DFS to mark all reachable cells from (0, 0)
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                dfs(ni, nj)

        # Second DFS to mark all reachable cells from (m-1, n-1)
        dfs(m - 1, n - 1)

        dq = deque([(0, 0)])
        grid[0][0] = 0
        dirs = [(1, 0), (0, 1)]

        while dq:
            l = len(dq)
            for _ in range(l):
                i, j = dq.popleft()
                if i == m - 1 and j == n - 1:
                    return False
                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 2:
                        dq.append((ni, nj))
                        grid[ni][nj] = 0
            if len(dq) == 1 and dq[0] != (m - 1, n - 1):
                return True

        return True

class Solution:
    def findComplement(self, num: int) -> int:
        com = ''
        while num > 0:
            if num % 2 == 1:
                com += '0'
            else:
                com += '1'
            num = num // 2
        return int(com[::-1][1:], 2)

class Solution:
    def gridGame(self, grid: List[List[int]]) -> int:
        result = float("inf")
        left, right = 0, sum(grid[0])

        for a, b in zip(grid[0], grid[1]):
            right -= a

            result = min(result, max(left, right))
            left += b

        return result

