from typing import List

class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        if not words or len(words) == 0:
            return []

        wlen = len(words[0])
        slen = wlen * len(words)
        track = dict()
        occ = Counter(words)
        res = []

        def test():
            for key, val in track.items():
                if val != occ[key]:
                    return False
            return True

        for k in range(wlen):
            track = dict()
            for i in range(k, len(s) - slen + 1, wlen):
                w = s[i:i + wlen]
                if w in occ:
                    track[w] = track.get(w, 0) + 1
                if test():
                    res.append(i)
                if i + wlen < len(s):
                    nw = s[i + wlen:i + wlen + wlen]
                    pw = s[i - wlen:i]
                    if nw in occ:
                        track[nw] = track.get(nw, 0) + 1
                    if pw in occ:
                        track[pw] = track.get(pw, 0) - 1
        return res

class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        # simple validation
        n = len(lcp)
        for i in range(n):
            for j in range(i + 1, n):
                if lcp[i][j] == lcp[j][i]:
                    return ''
                if lcp[i][j] > n - j:
                    return ''
        for i in range(n):
            if lcp[i][i] == n - i:
                return ''

        # build pattern \u2014 the only possible candidate for answer
        pattern = [None for _ in range(n)]
        next_el_ind = 0
        for i in range(n):
            if pattern[i] is not None:
                continue
            pattern[i] = next_el_ind
            next_el_ind += 1
            for j in range(i+1, n):
                if lcp[i][j] > 0:
                    if pattern[j] is not None and pattern[j] != pattern[i]:
                        return ''
                    pattern[j] = pattern[i]

        # check if lcp is valid - check that pattern's lcp == original lcp
        pattern_lcp = [[0 for _ in range(n)] for _ in range(n)]
        for i in range(n-1, -1, -1):
            for j in range(n-1, -1, -1):
                if pattern[i] == pattern[j]:
                    if max(i, j) + 1 < n:
                        pattern_lcp[i][j] = pattern_lcp[i+1][j+1] + 1
                    else:
                        pattern_lcp[i][j] = 1
        for i in range(n):
            for j in range(n):
                if lcp[i][j] != pattern_lcp[i][j]:
                    return ''

        # check that answer has no more than 26 distinct elements
        if max(pattern) >= ord('z') - ord('a') + 1:
            return ''

        return ''.join(chr(ord('a') + ind) for ind in pattern)

class Solution:
    def cdist(self, it, distArray, distArrayIndex, edges):
        rdist = 0 
        nodes = []
        while it != -1 and distArray[it+1][distArrayIndex] > rdist:
            distArray[it][distArrayIndex] = rdist
            nodes.append(it)
            it = edges[it]
            rdist += 1
        return nodes

    def closestMeetingNode(self, edges: List[int], node1: int, node2: int) -> int:
        INF = float('inf')
        dist = defaultdict(lambda: [INF, INF])
        mmin, ans = INF, -1

        n = self.cdist(node1, dist, 0, edges)
        n += self.cdist(node2, dist, 1, edges)

        for k in n:
            m = max(dist[k])
            if m != INF:
                if m < mmin: 
                    mmin = m
