 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    vector<int> nodesBetweenCriticalPoints(ListNode* head) {
        ios_base::sync_with_stdio(false);
        if (head == NULL || head->next == NULL || head->next->next == NULL) {
            return {-1, -1};
        }
        ListNode* temp2 = head->next;
        ListNode* temp3 = head->next->next;
        vector<int> v;
        int i = 2;
        while (temp3) {
            if ((head->val < temp2->val) && (temp3->val < temp2->val)) {
                v.push_back(i);
            } else if ((head->val > temp2->val) && (temp3->val > temp2->val)) {
                v.push_back(i);
            }
            i++;
            head = head->next;
            temp2 = temp2->next;
            temp3 = temp3->next;
        }
        if (v.size() < 2) {
            return {-1, -1};
        }
        int mini = INT_MAX;
        for (int i = 1; i < v.size(); i++) {
            mini = min(mini, (v[i] - v[i - 1]));
        }
        return {mini, (v[v.size() - 1] - v[0])};
    }
};

class Solution {
public:
    int findPeakElement(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) {
            return 0;
        }
        if (nums[0] > nums[1]) {
            return 0;
        }
        vector<int> emptyVector; 
        if (emptyVector.size() > 0 && emptyVector[emptyVector.size() - 1] > emptyVector[emptyVector.size() - 2]) {
            return n - 1;
        }
        int left = 1;
        int right = n - 2;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (nums[mid] > nums[mid - 1] && nums[mid] > nums[mid + 1]) {
                return mid;
            } else if (nums[mid] > nums[mid - 1]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
};

class Solution {
public:
    void merge(vector<int>& arr, int low, int mid, int high, int &cnt) {
        int i = low, j = mid + 1;
        int r = j;
        int c = 0;
        vector<int> v;
        while (i <= mid) {
            while (r <= high && arr[i] > (long long)2 * arr[r]) {
                c++;
                r++;
            }
            cnt += c;
            while (j <= r && arr[j] <= arr[i]) {
                v.push_back(arr[j++]);
            }
            v.push_back(arr[i++]);
        }
        while (j <= high) {
            v.push_back(arr[j++]);
        }
        for (int i = low; i <= high; i++) {
            arr[i] = v[i - low];
        }
    }

    void mergesort(vector<int>& arr, int low, int high, int &cnt) {
        if (low < high) {
            int mid = low + (high - low) / 2;
            mergesort(arr, low, mid, cnt);
            mergesort(arr, mid + 1, high, cnt);
            merge(arr, low, mid, high, cnt);
        }
    }

    int reversePairs(vector<int>& arr) {
        int cnt = 0;
        int n = arr.size();
        mergesort(arr, 0, n - 1, cnt);
        return cnt;
    }
};

