            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && vis[i][j] == 0) {
                    dfs(i, j, v, vis, grid);
                    if (!flag) {
                        v1 = v;
                        flag = true;
                        v.clear();
                    } else {
                        v2 = v;
                    }
                }
            }
        }

        int ans = 1e9;

        for (auto it : v1) {
            int row1 = it.first;
            int col1 = it.second;

            for (auto itt : v2) {
                int row2 = itt.first;
                int col2 = itt.second;

                int dist = abs(row1 - row2) + abs(col1 - col2);
                ans = min(ans, dist);
            }
        }

        return ans;
    }
};

class Solution {
public:
    void bfs(int prevcolor, int row, int col, int color, vector<vector<int>>& visited, vector<vector<int>>& image) {
        // It'll ease the work
        queue<pair<int, int>> q;
        q.push({row, col});
        visited[row][col] = 1;

        while (!q.empty()) {
            row = q.front().first;
            col = q.front().second;
            q.pop();

            /* If the image is of the starting color. */
            if (image[row][col] == prevcolor) {
                image[row][col] = color;
            }

            // Up
            if (row - 1 >= 0 && !visited[row - 1][col] && image[row - 1][col] == prevcolor) {
                q.push({row - 1, col});
                visited[row - 1][col] = 1;
                image[row - 1][col] = color;
            }

            // Right
            if (col + 1 < image[0].size() && !visited[row][col + 1] && image[row][col + 1] == prevcolor) {
                q.push({row, col + 1});
                visited[row][col + 1] = 1;
                image[row][col + 1] = color;
            }

            // Down
            if (row + 1 < image.size() && !visited[row + 1][col] && image[row + 1][col] == prevcolor) {
                q.push({row + 1, col});
                visited[row + 1][col] = 1;
                image[row + 1][col] = color;
            }

            // Left
            if (col - 1 >= 0 && !visited[row][col - 1] && image[row][col - 1] == prevcolor) {
                q.push({row, col - 1});
                visited[row][col - 1] = 1;
                image[row][col - 1] = color;
            }
        }
    }

