class Solution {
public:
    vector<int> numMovesStonesII(vector<int>& stones) {
        sort(stones.begin(), stones.end());

        int N = stones.size(), low = N;
        for (int i = 0, j = 0; j < N; ++j) {
            while (stones[j] - stones[i] + 1 > N) {
                ++i;
            }
            int gap = stones[j] - stones[i] + 1;
            int current = N - (j - i + 1);
            if (gap == N && current == N) {
                low = calculateLow(low, 2);
            } else if (gap == N || current == N) {
                low = calculateLow(low, 1);
            } else {
                low = calculateLow(low, current);
            }
        }

        int high = 1 + max((stones[N - 1] - stones[1] + 1) - N,  // Move to right most
                           (stones[N - 2] - stones[0] + 1) - N); // Move to left most
        return {low, high};
    }

private:
    int calculateLow(int currentLow, int value) {
        return min(currentLow, value);
    }
};

