class Solution {
public:
    std::vector<int> closestPrimes(int left, int right) {
        if (left == 1) left++;
        std::vector<bool> isPrime(right + 1, true);
        for (int i = 2; i <= std::sqrt(right); i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= right; j += i) {
                    isPrime[j] = false;
                }
            }
        }

        int i = left;
        while (i <= right && !isPrime[i]) {
            i++;
        }

        int a = -1, b = -1, minDiff = INT_MAX;
        while (i <= right) {
            if (isPrime[i]) {
                int j = i + 1;
                while (j <= right && !isPrime[j]) {
                    j++;
                }
                if (j <= right) {
                    int diff = j - i;
                    if (diff < minDiff) {
                        minDiff = diff;
                        a = i;
                        b = j;
                    }
                }
                i = j;
            } else {
                i++;
            }
        }

        return {a, b};
    }
};

class Solution {
public:
    int findPeakElement(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) {
            return 0;
        }
        if (nums[0] > nums[1]) {
            return 0;
        }
        if (nums[n - 1] > nums[n - 2]) {
            return n - 1;
        }
        int left = 1;
        int right = n - 2;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (nums[mid] > nums[mid - 1] && nums[mid] > nums[mid + 1]) {
                return mid;
            } else if (nums[mid] > nums[mid - 1]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }
};

