class Solution {
public:
    int solve(int left, int right) {
        int bit1 = log2(left);
        int bit2 = log2(right);
        if (bit1 < bit2) return 0;
        return (1 << bit1) | solve((left ^ (1 << bit1)), (right ^ (1 << bit1)));
    }
    int rangeBitwiseAnd(int left, int right) {
        return solve(left, right);
    }
};

class Solution {
public:
    int solve(int n) {
        vector<int> dp(n + 1, 0);    
        dp[0] = dp[1] = 1;
        for (int i = 2; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                dp[i] += dp[j - 1] * dp[i - j];
            }
        }
        return dp[n];
    }

    int numTrees(int n) {
        return solve(n); 
    }
};

