        while (i <= j) {
            int mid = i + (j - i) / 2;
            if (val == bv[mid]) return val;
            if (val < bv[mid]) {
                ans = bv[mid];
                j = mid - 1;
            } else {
                i = mid + 1;
            }
        }
        return ans;
    }

    vector<vector<int>> closestNodes(TreeNode* root, vector<int>& queries) {
        list<int> bv;
        vector<vector<int>> ans;
        dfs(root, bv);
        for (auto q : queries) {
            int lb = min1(bv, q);
            int ub = max1(bv, q);
            ans.push_back({lb, ub});
        }
        return ans;
    }
};

