class Solution {
public:
    ListNode* sortList(ListNode* head) {
        vector<int> vec1;
        ListNode* temp = head;
        while (temp != nullptr) {
            vec1.push_back(temp->val);
            temp = temp->next;
        }
        sort(vec1.begin(), vec1.end());
        ListNode* curr = head;
        for (int i = 0; i < vec1.size(); i++) {
            curr->val = vec1[i];
            curr = curr->next;
        }
        return head;
    }
};

class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        // array to store max length subsequence till that place
        vector<int> dp(nums.size(), 0);
        int maxlength = 0; // to store max length of subsequence
        dp[0] = 1; // length will be 1 at first index 
        for (int i = 0; i < nums.size(); i++) {
            int currentMaxLen = 0; // to store max length till this index
            for (int j = 0; j < i; j++) {
                // only check when the subsequence is increasing
                if (nums[i] > nums[j]) {
                    if (currentMaxLen < dp[j]) {
                        currentMaxLen = dp[j]; // update currentMaxLen accordingly
                    }
                }
            }
            dp[i] = currentMaxLen + 1; // set the max length till ith index, which will be max length so far + 1
            maxlength = max(maxlength, dp[i]); // update max length
        }

        return maxlength;
    }
};

