class Solution {
public:
    std::vector<int> countsort(std::vector<int> &nums)
    {
        int n = nums.size();
        std::map<int, int> m;
        for (int i = 0; i < n; i++)
            m[nums[i]]++;

        nums.clear();
        for (auto it = m.begin(); it != m.end(); ++it)
        {
            int cnt = it->second;
            while (cnt--)
            {
                nums.push_back(it->first);
            }
        }
        return nums;
    }

    int maximumGap(std::vector<int> &nums)
    {
        int n = nums.size();
        if (n < 2)
            return 0;
        std::vector<int> sortednums = countsort(nums);

        int maxgap = INT_MIN;
        for (int i = 1; i < n; i++)
        {
            int currgap = sortednums[i] - sortednums[i - 1];
            maxgap = std::max(maxgap, currgap);
        }

        return maxgap;
    }
};

