class Solution {
public:
    void fliprow(int r, vector<vector<int>>& grid) {
        for(int i = 0; i < grid[0].size(); i++) {
            grid[r][i] = 1 - grid[r][i];
        }
    }

    void flipcol(int c, vector<vector<int>>& grid) {
        for(int j = 0; j < grid.size(); j++) {
            grid[j][c] = 1 - grid[j][c];
        }
    }

    int matrixScore(vector<vector<int>>& grid) {
        int n = grid.size();
        int m = grid[0].size();

        // Make the first column all 1s
        for(int i = 0; i < n; i++) {
            if(grid[i][0] == 0) {
                fliprow(i, grid);
            }
        }

        // Check each column (starting from index 1) and flip if more 0s
        for(int j = 1; j < m; j++) {
            int cnt0 = 0, cnt1 = 0;
            for(int i = 0; i < n; i++) {
                if(grid[i][j] == 1) cnt1++;
                else cnt0++;
            }
            if(cnt0 > cnt1) {
                flipcol(j, grid);
            }
        }

        // Calculate the final score
        int sum = 0;
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(grid[i][j] == 1) {
                    sum += (1 << (m - j - 1));
                }
            }
        }
        return sum;
    }
};

