class Solution {
public:
    vector<int> plusOne(vector<int>& digits) {
        int n = digits.size();
        digits[n - 1]++; 
        for(int i = n - 1; i >= 0; i--)
        {
            if(digits[i] > 9)
            {
                digits[i] %= 10;
                if (i > 0) {
                    digits[i - 1]++;
                } else {
                    // If we're at the first digit and it's still over 9, we need to insert a new digit
                    digits.insert(digits.begin(), 1);
                    digits[1] %= 10;
                }
            }
        }
        return digits;
    }
};

