        for (int n : nums) {
            if (n > x) {
                cnt++;
            }
        }
        return cnt;
    }

    public int specialArray(int[] nums) {
        int maxi = Integer.MIN_VALUE;
        for (int x : nums) {
            maxi = Math.max(maxi, x);
        }
        int start = 1, end = maxi;
        while (start <= end) {
            int mid = (start + end) / 2;
            int check = countPossibility(nums, mid);
            if (check == mid) {
                return mid;
            }
            if (mid < check) {
                start = mid + 1;
            } else {
                end = mid - 1;
            }
        }
        return -1;
    }
}

class Solution {
    boolean isSimilar(String str1, String str2) {
        int count = 0;
        for (int i = 0; i < str1.length(); i++) {
            if (str1.charAt(i) != str2.charAt(i)) {
                count++;
                if (count > 2) {
                    return false;
                }
            }
        }
        return count == 0 || count == 2;
    }

    void dfs(String curr, String[] strs, Set<String> visited) {
        if (visited.contains(curr)) {
            return;
        }
        visited.add(curr);
        for (int i = 0; i < strs.length; i++) {
            if (isSimilar(curr, strs[i])) {
                dfs(strs[i], strs, visited);
            }
        }
    }

    public int numSimilarGroups(String[] strs) {
        int count = 0;

        if (strs == null || strs.length == 0) {
            return 0;
        }

        Set<String> visited = new HashSet<>();
        for (String s : strs) {
            if (!visited.contains(s)) {
                dfs(s, strs, visited);
                count++;
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public int minJumps(int[] arr) {
        Map<Integer, ArrayList<Integer>> hm = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            if (hm.containsKey(arr[i])) {
                ArrayList<Integer> al = hm.get(arr[i]);
                al.add(i);
                hm.put(arr[i], al);
            } else {
                ArrayList<Integer> al = new ArrayList<>();
                al.add(i);
                hm.put(arr[i], al);
            }
        }
        boolean[] vis = new boolean[arr.length];
        Queue<Integer> q = new LinkedList<>();
        q.add(0);
        int cnt = 0;
        while (!q.isEmpty()) {
            for (int k = q.size(); k > 0; k--) {
                int n = q.remove();
                vis[n] = true;
                if (n == arr.length - 1) return cnt;
                ArrayList<Integer> al = hm.get(arr[n]);
                if (al != null) {
                    al.add(n - 1);
                    al.add(n + 1);
                }
                for (int i : al) {
                    if (i >= 0 && i < arr.length && !vis[i]) {
                        q.add(i);
                    }
                }
                al.clear();
            }
            cnt++;
        }
        return 0;
    }
}

