class Solution {

    int countDigits(int n) {
        if (n == 0) return 0;
        return 1 + countDigits(n / 10);
    }

    public int countLargestGroup(int n) {
        ArrayList<Integer> list = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            int cd = countDigits(i);
            if (cd >= list.size()) {
                list.add(0);
            }
            list.set(cd, list.get(cd) + 1);
        }
        return Collections.frequency(list, Collections.max(list));
    }
}

import java.util.*;

class Solution {
    public int minJumps(int[] arr) {
        Map<Integer, ArrayList<Integer>> hm = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            if (hm.containsKey(arr[i])) {
                ArrayList<Integer> al = hm.get(arr[i]);
                al.add(i);
                hm.put(arr[i], al);
            } else {
                ArrayList<Integer> al = new ArrayList<>();
                al.add(i);
                hm.put(arr[i], al);
            }
        }
        boolean[] vis = new boolean[arr.length];
        Queue<Integer> q = new LinkedList<>();
        q.add(0);
        int cnt = 0;
        while (!q.isEmpty()) {
            int size = q.size();
            for (int k = 0; k < size; k++) {
                int n = q.remove();
                vis[n] = true;
                if (n == arr.length - 1) return cnt;
                ArrayList<Integer> al = hm.get(arr[n]);
                if (al != null) {
                    al.add(n - 1);
                    al.add(n + 1);
                }
                for (int i : al) {
                    if (i >= 0 && i < arr.length && !vis[i]) {
                        q.add(i);
                    }
                }
            }
            cnt++;
        }
        return 0;
    }
}

class Solution {
    double possible = 0.0;
    double valid = 0.0;

    public double getProbability(int[] balls) {
        int[] first = new int[balls.length];
        int[] second = new int[balls.length];
        dfs(balls, first, second, 0, 0, 0);
        return valid / possible;
    }

    private void dfs(int[] balls, int[] first, int[] second, int num1, int num2, int idx) {
        if (idx == balls.length) {
            double distrib = permFake(first) * permFake(second);
            possible += distrib;
            if (unique(first) == unique(second)) {
                valid += distrib;
            }
            return;
        }
        for (int b = 0; b <= balls[idx]; b++) {
            first[idx] = b;
            second[idx] = balls[idx] - b;
            dfs(balls, first, second, num1 + first[idx], num2 + second[idx], idx + 1);
        }
    }

    private double permFake(int[] arr) {
        double res = 1.0;
        int total = 0;
        for (int num : arr) {
            total += num;
        }
        for (int i = total; i > 0; i--) {
            res *= i;
        }
        for (int num : arr) {
            if (num > 0) {
                res /= factorial(num);
            }
        }
        return res;
    }

    private int unique(int[] arr) {
        int count = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] != 0) {
                count++;
            }
        }
        return count;
    }

    private int factorial(int n) {
        int ret = 1;
        while (n > 0) {
            ret *= n;
            n--;
        }
        return ret;
    }
}

import java.util.*;

class Solution {
    public int minJumps(int[] arr) {
        Map<Integer, List<Integer>> hm = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            hm.putIfAbsent(arr[i], new ArrayList<>());
            hm.get(arr[i]).add(i);
        }

        boolean[] vis = new boolean[arr.length];
        Queue<Integer> q = new LinkedList<>();
        q.add(0);
        vis[0] = true;
        int cnt = 0;

        while (!q.isEmpty()) {
            int size = q.size();
            for (int k = 0; k < size; k++) {
                int n = q.poll();
                if (n == arr.length - 1) return cnt;

                // Add next index
                if (n + 1 < arr.length && !vis[n + 1]) {
                    vis[n + 1] = true;
                    q.add(n + 1);
                }

                // Add previous index
                if (n - 1 >= 0 && !vis[n - 1]) {
                    vis[n - 1] = true;
                    q.add(n - 1);
                }

                // Add all indices with the same value
                if (hm.containsKey(arr[n])) {
                    for (int next : hm.get(arr[n])) {
                        if (!vis[next]) {
                            vis[next] = true;
                            q.add(next);
                        }
                    }
                    hm.remove(arr[n]); // Avoid revisiting the same value
                }
            }
            cnt++;
        }
        return 0;
    }
}

class Solution {
    public String smallestEquivalentString(String s1, String s2, String baseStr) {

        UFDS dsu = new UFDS(26);
        for(int i = 0; i < s1.length(); i++){
            dsu.union(s1.charAt(i)-97, s2.charAt(i)-97);
        }

        StringBuilder sb = new StringBuilder(); 

        for(int i = 0; i < baseStr.length(); i++){
            int root = dsu.root(baseStr.charAt(i) - 97);
            sb.append((char)(dsu.min[root] + 97));
        }
        return sb.toString();
    }

    class UFDS{

        int[] id;
        int[] size;
        int[] min;

        public UFDS(int N){

            id = new int[N];
            size = new int[N];
            min = new int[N];
            for(int i = 0; i < N; i++){
                id[i] = i;
                size[i] = 1;
                min[i] = i;
            }
        }

        private int root(int i){
            while (i != id[i]){
                id[i] = id[id[i]];
                i = id[i];
            }
            return i;
        }

        public void union(int p, int q){

            int i = root(p);
            int j = root(q);
            if(i == j)return;
            if(size[i] < size[j]){
                id[i] = id[j];
                size[j] += size[i];
                min[j] = Math.min(min[i], min[j]);
            }
            else{
                id[j] = id[i];
                size[i] += size[j];
                min[i] = Math.min(min[i], min[j]);
            }
        }

    }   
}

